def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression containing non-negative integers, 
    the binary operators + - * /, parentheses, and spaces.

    The function uses a stack-based approach to parse the expression and 
    evaluate it. It handles integer division by truncating toward zero.

    :param expr: The arithmetic expression to be evaluated
    :return: The result of the evaluated expression
    """

    # Split the expression into tokens (operators and operands)
    tokens = []
    current_token = ''
    for char in expr:
        if char.isspace():
            if current_token:
                tokens.append(current_token)
                current_token = ''
        elif char in '+-*/()':
            if current_token:
                tokens.append(current_token)
                current_token = ''
            tokens.append(char)
        else:
            current_token += char
    if current_token:
        tokens.append(current_token)

    # Initialize the stack and the output
    output = []
    stack = []

    # Iterate over the tokens
    for token in tokens:
        # If the token is an operand, push it onto the output stack
        if token.isdigit():
            output.append(int(token))
        # If the token is an operator, pop two operands from the output stack, 
        # apply the operator, and push the result back onto the output stack
        elif token in '+-*/':
            operand2 = output.pop()
            operand1 = output.pop()
            if token == '+':
                output.append(operand1 + operand2)
            elif token == '-':
                output.append(operand1 - operand2)
            elif token == '*':
                output.append(operand1 * operand2)
            elif token == '/':
                output.append(operand1 // operand2)  # Use integer division
        # If the token is an opening parenthesis, push it onto the stack
        elif token == '(':
            stack.append(token)
        # If the token is a closing parenthesis, pop operators from the stack 
        # until we find the matching opening parenthesis, apply them, and 
        # discard the opening parenthesis
        elif token == ')':
            while stack and stack[-1] != '(':
                operand2 = output.pop()
                operand1 = output.pop()
                if stack[-1] == '+':
                    output.append(operand1 + operand2)
                elif stack[-1] == '-':
                    output.append(operand1 - operand2)
                elif stack[-1] == '*':
                    output.append(operand1 * operand2)
                elif stack[-1] == '/':
                    output.append(operand1 // operand2)
                stack.pop()
            stack.pop()  # Discard the opening parenthesis

    # The final result should be the only element left on the output stack
    return output[0]
