def fizzbuzz_list(n: int) -> list[str]:
    """
    Returns a list of strings for the integers 1..n: 
    'FizzBuzz' for multiples of 15, 'Fizz' for other multiples of 3, 
    'Buzz' for other multiples of 5, and the number itself as a string otherwise.
    Returns [] when n < 1.
    """
    if n < 1:
        return []

    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))

    return result
