    """
    Evaluate an arithmetic expression containing non-negative integers, 
    the binary operators + - * /, parentheses, and spaces.

    :param expr: The arithmetic expression to evaluate as a string
    :return: The result of the evaluation as an integer
    """
    # Remove all spaces from the expression
    expr = expr.replace(" ", "")

    # Evaluate the expression using the Shunting-yard algorithm
    def apply_operator():
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(int(left // right))  # Integer division truncates toward zero

    def precedence(operator):
        if operator in '+-':
            return 1
        if operator in '*/':
            return 2
        return 0

    values, operators = [], []
    precedence_map = {'+': 1, '-': 1, '*': 2, '/': 2}

    for char in expr:
        if char.isdigit():
            values.append(int(char))
        elif char in precedence_map:
            while operators and operators[-1] in precedence_map and precedence_map[operators[-1]] >= precedence(char):
                apply_operator()
            operators.append(char)
        elif char == '(':
            operators.append(char)
        elif char == ')':
            while operators[-1] != '(':
                apply_operator()
            operators.pop()  # Remove the '('

    while operators:
        apply_operator()

    return values[0]
