def lru_misses(capacity: int, requests: list[int]) -> int:
    cache = {}
    misses = 0
    i = 0
    while i < len(requests):
        if requests[i] in cache:
            del cache[requests[i]]
            cache[requests[i]] = i
        else:
            if len(cache) == capacity:
                lru_key = min(cache, key=cache.get)
                del cache[lru_key]
                misses += 1
            cache[requests[i]] = i
        i += 1
    return misses
