def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression containing non-negative integers, 
    the binary operators + - * /, parentheses, and spaces. 
    * and / bind tighter than + and -, and operators of equal precedence 
    associate left to right. Integer division truncates toward zero.

    :param expr: A string containing the arithmetic expression to be evaluated
    :return: The result of the evaluated expression
    """

    # Split the expression into tokens (operators and operands)
    tokens = []
    current_token = ""
    for char in expr:
        if char.isspace():
            if current_token:
                tokens.append(current_token)
                current_token = ""
        else:
            current_token += char
    if current_token:
        tokens.append(current_token)

    # Define operator precedence
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2
    }

    # Use a stack to evaluate the expression
    output_queue = []
    operator_stack = []
    for token in tokens:
        if token.isdigit():
            output_queue.append(int(token))
        elif token in precedence:
            while (operator_stack and 
                   operator_stack[-1] in precedence and 
                   precedence[operator_stack[-1]] >= precedence[token]):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack[-1] != '(':
                output_queue.append(operator_stack.pop())
            operator_stack.pop()  # Remove the '('

    # Evaluate any remaining operators
    while operator_stack:
        output_queue.append(operator_stack.pop())

    # Calculate the final result
    result = output_queue[0]
    i = 1
    while i < len(output_queue):
        if output_queue[i] == '+':
            result += output_queue[i + 1]
        elif output_queue[i] == '-':
            result -= output_queue[i + 1]
        elif output_queue[i] == '*':
            result *= output_queue[i + 1]
        elif output_queue[i] == '/':
            result //= output_queue[i + 1]
        i += 2

    return result
