def regex_match(s: str, p: str) -> bool:
    """
    Return True if pattern p matches the whole of s.

    In p, '.' matches any single character and '*' matches zero or more of the preceding element.
    Every '*' is preceded by a valid character or '.'.

    :param s: The string to match.
    :param p: The pattern to match against.
    :return: True if pattern p matches the whole of s, False otherwise.
    """
    def match(i, j):
        # If both indices are equal, it's a match.
        if i == j:
            return True
        # If the current character in p is '.', it matches any character in s.
        if p[j] == '.':
            return match(i + 1, j + 1)

        # If the current character in p is '*', it can match zero or more of the preceding element.
        if p[j] == '*':
            # If '*' matches zero characters, it's a match if the current index is equal to the previous index.
            if i <= j - 1 and p[j - 1] == s[i]:
                return match(i, j + 1)
            # If '*' matches one or more of the preceding element, it's a match if the current index is greater than the previous index.
            else:
                return match(i + 1, j)

        # If the current character in p is not '*' or '.', it's a character match.
        if i < len(s) and p[j] == s[i]:
            return match(i + 1, j + 1)
        # If it's not a match, it's not a match.
        return False

    # The whole string matches if the first index of the first substring is equal to the first index of the pattern.
    return match(0, 0)
