def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression containing non-negative integers, 
    the binary operators + - * /, parentheses, and spaces. * and / bind 
    tighter than + and -, and operators of equal precedence associate left to right. 
    Integer division truncates toward zero.
    """

    def apply_operator(operators, values):
        """
        Apply an operator to the top two values in the operator stack.
        """
        op = operators.pop()
        right = values.pop()
        left = values.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            values.append(left // right)  # Use // for integer division

    def precedence(op):
        """
        Get the precedence of an operator.
        """
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    def tokenize(expr):
        """
        Tokenize the input expression into operators and values.
        """
        tokens = []
        current_num = ''
        for char in expr:
            if char.isdigit():
                current_num += char
            elif char in '+-*/() ':
                if current_num:
                    tokens.append(int(current_num))
                    current_num = ''
                tokens.append(char)
        if current_num:
            tokens.append(int(current_num))
        return tokens

    def reverse Polish(expr):
        """
        Convert the input expression to Reverse Polish notation.
        """
        stack = []
        operators = []
        tokens = tokenize(expr)
        for token in tokens:
            if isinstance(token, int):
                stack.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, stack)
                operators.pop()  # Remove the '('
            else:
                while operators and operators[-1] != '(' and precedence(token) <= precedence(operators[-1]):
                    apply_operator(operators, stack)
                operators.append(token)
        while operators:
            apply_operator(operators, stack)
        return stack

    return reverse_Polish(expr)

